+++ b/lib/handler/mruby.c
@@ -253,6 +253,20 @@ mrb_value send_early_hints_proc(mrb_state *mrb, mrb_value self)
     return mrb_nil_value();
 }

+static mrb_value get_rtt_estimate_proc(mrb_state *mrb, mrb_value self)
+{
+    h2o_mruby_generator_t *generator = h2o_mruby_get_generator(mrb, mrb_proc_cfunc_env_get(mrb, 0));
+    if (generator == NULL)
+        return mrb_nil_value();
+    if (generator->req->conn->callbacks->get_rtt_estimate != NULL) {
+        int64_t rtt_us = generator->req->conn->callbacks->get_rtt_estimate(generator->req->conn);
+        if (rtt_us >= 0) {
+            return mrb_fixnum_value(rtt_us);
+        }
+    }
+    return mrb_nil_value();
+}
