@@ -319,6 +333,7 @@ static mrb_value build_constants(mrb_state *mrb, const char *server_name, size_t
     SET_LITERAL(H2O_MRUBY_LIT_SERVER_SOFTWARE, "SERVER_SOFTWARE");
     SET_LITERAL(H2O_MRUBY_LIT_H2O_REMAINING_DELEGATIONS, "h2o.remaining_delegations");
     SET_LITERAL(H2O_MRUBY_LIT_H2O_REMAINING_REPROCESSES, "h2o.remaining_reprocesses");
+    SET_LITERAL(H2O_MRUBY_LIT_H2O_GET_RTT_ESTIMATE, "h2o.get_rtt_estimate");
     SET_STRING(H2O_MRUBY_LIT_SERVER_SOFTWARE_VALUE, h2o_mruby_new_str(mrb, server_name, server_name_len));

 #undef SET_LITERAL
@@ -766,6 +781,10 @@ static mrb_value build_env(h2o_mruby_generator_t *generator)
         if (!mrb_nil_p(p))
             mrb_hash_set(mrb, env, mrb_ary_entry(shared->constants, H2O_MRUBY_LIT_REMOTE_PORT), p);
     }
+    if (generator->req->conn->callbacks->get_rtt_estimate != NULL) {
+        mrb_hash_set(mrb, env, mrb_ary_entry(shared->constants, H2O_MRUBY_LIT_H2O_GET_RTT_ESTIMATE),
+                     mrb_obj_value(mrb_proc_new_cfunc_with_env(mrb, get_rtt_estimate_proc, 1, &generator->refs.generator)));
+    }
     {
         size_t i;
         for (i = 0; i != generator->req->env.size; i += 2) {
diff --git a/lib/http2/connection.c b/lib/http2/connection.c
index 51400ef4a5..32d3538e0a 100644
--- a/lib/http2/connection.c
+++ b/lib/http2/connection.c
@@ -991,6 +991,9 @@ static int handle_settings_frame(h2o_http2_conn_t *conn, h2o_http2_frame_t *fram
             *err_desc = "invalid SETTINGS frame (+ACK)";
             return H2O_HTTP2_ERROR_FRAME_SIZE;
         }
+        if (conn->timestamps.settings_acked_at.tv_sec == 0 && conn->timestamps.settings_sent_at.tv_sec != 0) {
+            gettimeofday(&conn->timestamps.settings_acked_at, NULL);
+        }
     } else {
         uint32_t prev_initial_window_size = conn->peer_settings.initial_window_size;
         /* FIXME handle SETTINGS_HEADER_TABLE_SIZE */
@@ -1169,6 +1172,9 @@ static ssize_t expect_preface(h2o_http2_conn_t *conn, const uint8_t *src, size_t
             /* write origin frame */
             h2o_http2_encode_origin_frame(&conn->_write.buf, *conn->http2_origin_frame);
         }
+        if (conn->timestamps.settings_sent_at.tv_sec == 0) {
+            gettimeofday(&conn->timestamps.settings_sent_at, NULL);
+        }
         h2o_http2_conn_request_write(conn);
     }

@@ -1464,6 +1470,16 @@ static int skip_tracing(h2o_conn_t *_conn)
     return h2o_socket_skip_tracing(conn->sock);
 }

+static int64_t get_rtt_estimate(h2o_conn_t *_conn)
+{
+    struct st_h2o_http2_conn_t *conn = (void *)_conn;
+    if (conn->timestamps.settings_sent_at.tv_sec != 0 && conn->timestamps.settings_acked_at.tv_sec != 0) {
+        return h2o_timeval_subtract(&conn->timestamps.settings_sent_at, &conn->timestamps.settings_acked_at);
+    } else {
+        return -1;
+    }
+}
