diff --git a/t/50mruby-h2-rtt.t b/t/50mruby-h2-rtt.t
new file mode 100644
index 0000000000..7bc808eb97
--- /dev/null
+++ b/t/50mruby-h2-rtt.t
@@ -0,0 +1,43 @@
+use strict;
+use warnings;
+use Test::More;
+use t::Util;
+
+plan skip_all => 'mruby support is off'
+    unless server_features()->{mruby};
+
+plan skip_all => 'curl not found'
+    unless prog_exists('curl');
+
+subtest 'HTTP/2' => sub {
+    my $server = spawn_h2o(<< "EOT");
+num-threads: 1
+hosts:
+  default:
+    paths:
+      /:
+        mruby.handler-file: t/assets/50mruby-h2o-rtt.rb
+EOT
+    (undef, my $body) = run_prog("curl --http2 -sS http://127.0.0.1:$server->{port}/");
+    like $body, qr{^RTT = \d+$};
+    if ($body =~ qr{^RTT = (\d+)$}) {
+        my $rtt = $1;
+        # In the local test this can be 0us.
+        cmp_ok $rtt, '>=', 0, "The round-trip time estimate is $rtt microseconds.";
+    }
+};
+
+subtest 'HTTP/1.1' => sub {
+    my $server = spawn_h2o(<< "EOT");
+num-threads: 1
+hosts:
+  default:
+    paths:
+      /:
+        mruby.handler-file: t/assets/50mruby-h2o-rtt.rb
+EOT
+    (undef, my $body) = run_prog("curl --http1.1 -sS http://127.0.0.1:$server->{port}/");
+    like $body, qr{^RTT = N/A$};
+};
+
+done_testing;
diff --git a/t/assets/50mruby-h2o-rtt.rb b/t/assets/50mruby-h2o-rtt.rb
new file mode 100644
index 0000000000..55c606d902
--- /dev/null
+++ b/t/assets/50mruby-h2o-rtt.rb
@@ -0,0 +1,14 @@
+Proc.new do |env|
+  rtt = nil
+  unless env["h2o.get_rtt_estimate"].nil?
+    rtt = env["h2o.get_rtt_estimate"].call()
+    while rtt.nil? do
+      sleep(0.1)
+      rtt = env["h2o.get_rtt_estimate"].call()
+    end
+  end
+  if rtt.nil?
+    rtt = 'N/A'
+  end
+  [200, {}, ["RTT = ", rtt]]
+end
